import sys
import os
import time
if os.name == 'posix':
    import select, termios, tty
if os.name == 'nt':
    import msvcrt

_screen = []
_screenWidth = None
_screenHeight = None

_frameStartTime = None
_dirtyRowIndexs = set()
_previousDirtyRowIndexs = set()
_fd = None
_oldSettings = None
_currentKey = None

