# Shift+F1 ~ Shift+F8（内核里对应 F13~F20，号码跳号）
for _i, _n in enumerate((25, 26, 28, 29, 31, 32, 33, 34), start=1):
    LINUXKEYMAP[f"SHIFTF{_i}"] = ESC + b"[" + str(_n).encode() + b"~"


